create table if not exists public.cms_pages_v2(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,status text not null default 'draft' check(status in ('draft','published')),seo_title text,seo_description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.cms_blocks_v2(id uuid primary key default gen_random_uuid(),page_id uuid not null references public.cms_pages_v2(id) on delete cascade,block_type text not null,title text not null default '',subtitle text not null default '',body text not null default '',button_label text not null default '',button_href text not null default '',visible boolean not null default true,position integer not null default 0,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.cms_pages_v2 enable row level security; alter table public.cms_blocks_v2 enable row level security;
drop policy if exists cms_pages_public_read on public.cms_pages_v2; create policy cms_pages_public_read on public.cms_pages_v2 for select using(status='published');
drop policy if exists cms_blocks_public_read on public.cms_blocks_v2; create policy cms_blocks_public_read on public.cms_blocks_v2 for select using(visible=true and exists(select 1 from public.cms_pages_v2 p where p.id=cms_blocks_v2.page_id and p.status='published'));
create index if not exists cms_blocks_page_position on public.cms_blocks_v2(page_id,position);
insert into public.cms_pages_v2(slug,title,status,seo_title,seo_description) values('home','Home','draft','Zerion X1','Zerion X1 trading intelligence operating system'),('pricing','Pricing','draft','Zerion X1 Pricing','Plans for Zerion X1') on conflict(slug) do nothing;
